from itertools import combinations
from pysat.solvers import Glucose3

n = 13
edges = []
edge_index = {}
for i in range(n):
    for j in range(i+1, n):
        edge_index[(i,j)] = len(edges)
        edges.append((i,j))

fixed = {
    3: 1, 6: 0, 13: 0, 19: 0, 27: 0, 34: 1, 35: 0, 
    43: 1, 56: 1, 63: 0, 65: 1, 74: 0, 75: 0, 76: 0, 77: 0
}

solver = Glucose3()

# Add fixed assignments
for idx, val in fixed.items():
    if val == 1:
        solver.add_clause([idx + 1])
    else:
        solver.add_clause([-(idx + 1)])

# For each 4-clique, add constraints
for clique in combinations(range(n), 4):
    clique_edges = []
    for i in range(4):
        for j in range(i+1, 4):
            u, v = clique[i], clique[j]
            if u > v:
                u, v = v, u
            clique_edges.append(edge_index[(u,v)] + 1)

    # Not all red
    solver.add_clause(clique_edges)
    # Not all blue
    solver.add_clause([-e for e in clique_edges])

result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    model_set = set(model)
    solution = []
    for i in range(78):
        var = i + 1
        if var in model_set:
            solution.append(1)
        else:
            solution.append(0)

    print(f"Solution: {solution}")

    # Verify fixed assignments
    print("\nVerifying fixed assignments:")
    all_ok = True
    for idx, val in sorted(fixed.items()):
        if solution[idx] != val:
            print(f"  MISMATCH: c[{idx}] = {solution[idx]}, expected {val}")
            all_ok = False

    if all_ok:
        print("All fixed assignments satisfied!")

    # Verify no monochromatic K4
    print("\nVerifying no monochromatic K4:")
    violations = 0
    for clique in combinations(range(n), 4):
        clique_edges = []
        for i in range(4):
            for j in range(i+1, 4):
                u, v = clique[i], clique[j]
                if u > v: u, v = v, u
                clique_edges.append(solution[edge_index[(u,v)]])
        if all(c == 0 for c in clique_edges):
            print(f"  Red K4 found: {clique}")
            violations += 1
        if all(c == 1 for c in clique_edges):
            print(f"  Blue K4 found: {clique}")
            violations += 1

    if violations == 0:
        print("No monochromatic K4 found - solution is valid!")
